import torch
from vgg_lite_model import VGG_Lite_INT8
from brevitas.export import export_qonnx

def main():
    print("Loading VGG-Lite INT8 model architecture...")
    model = VGG_Lite_INT8()
    
    # Load the best weights generated by our training loop
    try:
        model.load_state_dict(torch.load('vgg_lite_int8_best.pth', map_location='cpu'))
        print("Successfully loaded trained weights from 'vgg_lite_int8_best.pth'!")
    except FileNotFoundError:
        print("Warning: 'vgg_lite_int8_best.pth' not found.")
        print("Make sure the training script has finished and saved the model.")
        return
    
    # Set model to evaluation mode (important for fixing scales and batch norms)
    model.eval()
    
    # Create a dummy input tensor matching CIFAR-10 format:
    # (Batch Size = 1, Channels = 3, Height = 32, Width = 32)
    dummy_input = torch.randn(1, 3, 32, 32)
    
    export_path = "vgg_lite_int8.onnx"
    print(f"Exporting model to {export_path}...")
    
    # Export the quantized model to QONNX format (The standard required by FINN)
    export_qonnx(model, input_t=dummy_input, export_path=export_path)
    
    print("Export complete!")
    print(f"The file '{export_path}' is now ready to be processed by the FINN compiler.")

if __name__ == '__main__':
    main()